# Check density of setAB at various scales
def setA(n):
    if n == 0: return True
    d = []
    x = n
    while x > 0:
        d.append(x % 3)
        x //= 3
    return all(di <= 1 for di in d)

def setB(n):
    if n == 0: return True
    d = []
    x = n
    while x > 0:
        d.append(x % 4)
        x //= 4
    return all(di <= 1 for di in d)

# Precompute setAB up to large N
N = 200000
in_setAB = set()
As = [a for a in range(N) if setA(a)]
Bs = [b for b in range(N) if setB(b)]
for a in As:
    for b in Bs:
        if a + b < N:
            in_setAB.add(a + b)

# Check density at various points
for N_test in [64, 243, 729, 2187, 6561, 19683, 59049]:
    if N_test <= N:
        cnt = sum(1 for x in range(N_test) if x in in_setAB)
        print(f'N={N_test}: |setAB|={cnt}, density={cnt/N_test:.4f}')

# Check near gap starts for aligned (k,m) pairs
